// Initialize monitoring and logging cycle
const triggerData = $input.first().json;
const triggerType = $node['Monitoring Trigger'].isRunning ? 'scheduled' : 'manual';

const monitoringConfig = {
  monitoring_id: `monitor_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
  trigger_type: triggerType,
  timestamp: new Date().toISOString(),
  manual_settings: triggerData || {},
  monitoring_parameters: {
    health_checks: triggerData.health_checks !== false, // default true
    performance_metrics: triggerData.performance_metrics !== false,
    error_detection: triggerData.error_detection !== false,
    log_aggregation: triggerData.log_aggregation !== false,
    alert_thresholds: triggerData.alert_thresholds || {
      error_rate: 0.05, // 5% error rate threshold
      response_time: 5000, // 5 second response time threshold
      memory_usage: 0.8, // 80% memory usage threshold
      cascade_depth: 5, // cascade depth threshold
      event_frequency: 100 // events per minute threshold
    },
    monitoring_scope: triggerData.scope || {
      systems: ['all'], // world-evolution, event-cascade, faction-manager, economic-simulator, seasonal-time
      campaigns: ['all'], // all campaigns or specific ones
      severity_levels: ['all'], // all severity levels or specific ones
      time_window: 'last_hour' // last_hour, last_day, last_week
    }
  },
  logging_parameters: {
    log_level: triggerData.log_level || 'info', // debug, info, warn, error, fatal
    log_categories: triggerData.log_categories || ['all'], // performance, errors, events, cascades, user_actions
    retention_period: triggerData.retention_period || '7_days', // 1_day, 7_days, 30_days, permanent
    structured_logging: triggerData.structured_logging !== false,
    correlation_ids: triggerData.correlation_ids !== false
  }
};

return [{ json: monitoringConfig }];

// Process campaign metrics and prepare monitoring analysis
const monitoringConfig = $input.first().json;
const campaigns = $input.last().json.results || [];

const processedCampaigns = campaigns.map(campaign => {
  const { campaignId, campaignName, worldState, systemMetrics, lastHealthCheck } = campaign;

  // Calculate health metrics
  const healthMetrics = calculateHealthMetrics(campaignId, worldState, systemMetrics);

  // Analyze system performance
  const performanceAnalysis = analyzeSystemPerformance(campaignId, systemMetrics, worldState);

  // Detect anomalies and issues
  const anomalyDetection = detectAnomalies(campaignId, healthMetrics, performanceAnalysis, monitoringConfig.monitoring_parameters.alert_thresholds);

  // Generate log entries
  const logEntries = generateLogEntries(campaignId, healthMetrics, performanceAnalysis, anomalyDetection, monitoringConfig.logging_parameters);

  return {
    campaignId,
    campaignName,
    healthMetrics,
    performanceAnalysis,
    anomalyDetection,
    logEntries,
    lastHealthCheck,
    systemMetrics: systemMetrics || {},
    monitoringPriority: calculateMonitoringPriority(healthMetrics, anomalyDetection)
  };
});

// Sort campaigns by monitoring priority (issues first)
processedCampaigns.sort((a, b) => b.monitoringPriority - a.monitoringPriority);

function calculateHealthMetrics(campaignId, worldState, systemMetrics) {
  const metrics = {
    overall_health: 'healthy', // healthy, warning, critical, unknown
    system_health: {},
    data_integrity: {},
    performance_indicators: {},
    resource_usage: {},
    error_rates: {},
    last_updated: new Date().toISOString()
  };

  // World state health
  if (worldState) {
    metrics.system_health.world_state = {
      status: 'healthy',
      locations_count: worldState.locations?.length || 0,
      npcs_count: worldState.npcs?.length || 0,
      factions_count: worldState.factions?.length || 0,
      quests_count: worldState.quests?.length || 0,
      last_modified: worldState.last_updated || 'unknown',
      data_completeness: calculateDataCompleteness(worldState)
    };
  } else {
    metrics.system_health.world_state = {
      status: 'critical',
      issue: 'world_state_missing',
      message: 'World state data is missing or corrupted'
    };
  }

  // System metrics health
  if (systemMetrics) {
    metrics.system_health.system_metrics = {
      status: 'healthy',
      last_collected: systemMetrics.last_collected || 'unknown',
      cpu_usage: systemMetrics.cpu_usage || 0,
      memory_usage: systemMetrics.memory_usage || 0,
      disk_usage: systemMetrics.disk_usage || 0,
      network_latency: systemMetrics.network_latency || 0
    };

    // Check resource thresholds
    if (systemMetrics.memory_usage > 0.8) {
      metrics.system_health.system_metrics.status = 'warning';
    }
    if (systemMetrics.memory_usage > 0.95) {
      metrics.system_health.system_metrics.status = 'critical';
    }
  } else {
    metrics.system_health.system_metrics = {
      status: 'warning',
      issue: 'system_metrics_missing',
      message: 'System metrics are not being collected'
    };
  }

  // Data integrity checks
  metrics.data_integrity = {
    world_state_consistency: checkWorldStateConsistency(worldState),
    relationship_integrity: checkRelationshipIntegrity(worldState),
    temporal_integrity: checkTemporalIntegrity(worldState),
    referential_integrity: checkReferentialIntegrity(worldState)
  };

  // Performance indicators
  metrics.performance_indicators = {
    response_time: calculateAverageResponseTime(systemMetrics),
    throughput: calculateThroughput(systemMetrics),
    availability: calculateAvailability(systemMetrics),
    efficiency: calculateEfficiency(worldState, systemMetrics)
  };

  // Error rates
  metrics.error_rates = {
    system_errors: calculateSystemErrorRate(systemMetrics),
    data_errors: calculateDataErrorRate(worldState),
    network_errors: calculateNetworkErrorRate(systemMetrics),
    user_errors: calculateUserErrorRate(systemMetrics)
  };

  // Calculate overall health
  const healthScore = calculateOverallHealthScore(metrics);
  if (healthScore >= 90) metrics.overall_health = 'healthy';
  else if (healthScore >= 70) metrics.overall_health = 'warning';
  else if (healthScore >= 50) metrics.overall_health = 'critical';
  else metrics.overall_health = 'unknown';

  return metrics;
}

function calculateDataCompleteness(worldState) {
  if (!worldState) return 0;

  const requiredFields = ['locations', 'npcs', 'factions', 'quests'];
  const presentFields = requiredFields.filter(field => 
    worldState[field] && Array.isArray(worldState[field]) && worldState[field].length > 0
  );

  return (presentFields.length / requiredFields.length) * 100;
}

function checkWorldStateConsistency(worldState) {
  if (!worldState) return { status: 'unknown', issues: ['no_data'] };

  const issues = [];

  // Check for duplicate IDs
  const checkDuplicates = (array, fieldName) => {
    if (!array || !Array.isArray(array)) return;
    const ids = array.map(item => item.id).filter(Boolean);
    const duplicates = ids.filter((id, index) => ids.indexOf(id) !== index);
    if (duplicates.length > 0) {
      issues.push(`duplicate_${fieldName}_ids: ${duplicates.join(', ')}`);
    }
  };

  checkDuplicates(worldState.locations, 'location');
  checkDuplicates(worldState.npcs, 'npc');
  checkDuplicates(worldState.factions, 'faction');
  checkDuplicates(worldState.quests, 'quest');

  // Check for orphaned references
  if (worldState.npcs && worldState.locations) {
    const locationIds = new Set(worldState.locations.map(l => l.id));
    const orphanedNPCs = worldState.npcs.filter(npc => 
      npc.location_id && !locationIds.has(npc.location_id)
    );

    if (orphanedNPCs.length > 0) {
      issues.push(`orphaned_npcs: ${orphanedNPCs.length} NPCs reference non-existent locations`);
    }
  }

  return {
    status: issues.length === 0 ? 'consistent' : 'inconsistent',
    issues,
    issue_count: issues.length
  };
}

function checkRelationshipIntegrity(worldState) {
  if (!worldState) return { status: 'unknown', issues: ['no_data'] };

  const issues = [];

  // Check NPC relationships
  if (worldState.npcs) {
    worldState.npcs.forEach(npc => {
      if (npc.relationships && typeof npc.relationships === 'object') {
        Object.entries(npc.relationships).forEach(([targetId, relationship]) => {
          const targetNPC = worldState.npcs.find(n => n.id === targetId);
          if (!targetNPC) {
            issues.push(`invalid_npc_relationship: ${npc.name} -> ${targetId}`);
          }
        });
      }
    });
  }

  // Check faction relationships
  if (worldState.factions) {
    worldState.factions.forEach(faction => {
      if (faction.relationships && typeof faction.relationships === 'object') {
        Object.entries(faction.relationships).forEach(([targetId, relationship]) => {
          const targetFaction = worldState.factions.find(f => f.id === targetId);
          if (!targetFaction) {
            issues.push(`invalid_faction_relationship: ${faction.name} -> ${targetId}`);
          }
        });
      }
    });
  }

  return {
    status: issues.length === 0 ? 'intact' : 'corrupted',
    issues,
    issue_count: issues.length
  };
}

function checkTemporalIntegrity(worldState) {
  if (!worldState) return { status: 'unknown', issues: ['no_data'] };

  const issues = [];
  const now = new Date();

  // Check for future timestamps
  const checkFutureTimestamps = (array, fieldName) => {
    if (!array || !Array.isArray(array)) return;
    array.forEach(item => {
      if (item.created_at && new Date(item.created_at) > now) {
        issues.push(`future_timestamp_${fieldName}: ${item.id}`);
      }
    });
  };

  checkFutureTimestamps(worldState.locations, 'location');
  checkFutureTimestamps(worldState.npcs, 'npc');
  checkFutureTimestamps(worldState.factions, 'faction');
  checkFutureTimestamps(worldState.quests, 'quest');

  // Check for stale data (older than 30 days without updates)
  const thirtyDaysAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
  if (worldState.last_updated && new Date(worldState.last_updated) < thirtyDaysAgo) {
    issues.push('stale_world_state: world state not updated in 30 days');
  }

  return {
    status: issues.length === 0 ? 'valid' : 'invalid',
    issues,
    issue_count: issues.length
  };
}

function checkReferentialIntegrity(worldState) {
  if (!worldState) return { status: 'unknown', issues: ['no_data'] };

  const issues = [];

  // Check quest giver references
  if (worldState.quests && (worldState.npcs || worldState.factions)) {
    worldState.quests.forEach(quest => {
      if (quest.giver_id) {
        const giverNPC = worldState.npcs?.find(n => n.id === quest.giver_id);
        const giverFaction = worldState.factions?.find(f => f.id === quest.giver_id);

        if (!giverNPC && !giverFaction) {
          issues.push(`invalid_quest_giver: quest ${quest.id} references non-existent giver ${quest.giver_id}`);
        }
      }

      if (quest.location_id && worldState.locations) {
        const location = worldState.locations.find(l => l.id === quest.location_id);
        if (!location) {
          issues.push(`invalid_quest_location: quest ${quest.id} references non-existent location ${quest.location_id}`);
        }
      }
    });
  }

  return {
    status: issues.length === 0 ? 'intact' : 'broken',
    issues,
    issue_count: issues.length
  };
}

function calculateAverageResponseTime(systemMetrics) {
  if (!systemMetrics || !systemMetrics.response_times) return 0;

  const times = systemMetrics.response_times;
  return times.reduce((sum, time) => sum + time, 0) / times.length;
}

function calculateThroughput(systemMetrics) {
  if (!systemMetrics || !systemMetrics.requests_per_minute) return 0;
  return systemMetrics.requests_per_minute;
}

function calculateAvailability(systemMetrics) {
  if (!systemMetrics || !systemMetrics.uptime_percentage) return 0;
  return systemMetrics.uptime_percentage;
}

function calculateEfficiency(worldState, systemMetrics) {
  if (!worldState || !systemMetrics) return 0;

  // Simple efficiency calculation based on resource usage vs data size
  const dataSize = JSON.stringify(worldState).length;
  const memoryUsage = systemMetrics.memory_usage || 0;

  if (memoryUsage === 0) return 100;

  return Math.max(0, 100 - (memoryUsage * 100));
}

function calculateSystemErrorRate(systemMetrics) {
  if (!systemMetrics || !systemMetrics.error_count || !systemMetrics.total_requests) return 0;
  return (systemMetrics.error_count / systemMetrics.total_requests) * 100;
}

function calculateDataErrorRate(worldState) {
  if (!worldState) return 100; // 100% error rate if no data

  const totalEntities = 
    (worldState.locations?.length || 0) +
    (worldState.npcs?.length || 0) +
    (worldState.factions?.length || 0) +
    (worldState.quests?.length || 0);

  if (totalEntities === 0) return 0;

  // Count entities with missing required fields
  let errorCount = 0;

  if (worldState.locations) {
    errorCount += worldState.locations.filter(l => !l.id || !l.name).length;
  }

  if (worldState.npcs) {
    errorCount += worldState.npcs.filter(n => !n.id || !n.name).length;
  }

  if (worldState.factions) {
    errorCount += worldState.factions.filter(f => !f.id || !f.name).length;
  }

  if (worldState.quests) {
    errorCount += worldState.quests.filter(q => !q.id || !q.name).length;
  }

  return (errorCount / totalEntities) * 100;
}

function calculateNetworkErrorRate(systemMetrics) {
  if (!systemMetrics || !systemMetrics.network_errors || !systemMetrics.total_requests) return 0;
  return (systemMetrics.network_errors / systemMetrics.total_requests) * 100;
}

function calculateUserErrorRate(systemMetrics) {
  if (!systemMetrics || !systemMetrics.user_errors || !systemMetrics.user_actions) return 0;
  return (systemMetrics.user_errors / systemMetrics.user_actions) * 100;
}

function calculateOverallHealthScore(metrics) {
  let score = 100;

  // System health penalties
  Object.values(metrics.system_health).forEach(health => {
    if (health.status === 'warning') score -= 10;
    if (health.status === 'critical') score -= 30;
    if (health.status === 'unknown') score -= 20;
  });

  // Data integrity penalties
  Object.values(metrics.data_integrity).forEach(integrity => {
    if (integrity.status !== 'consistent' && integrity.status !== 'intact' && integrity.status !== 'valid') {
      score -= integrity.issue_count * 5;
    }
  });

  // Performance penalties
  if (metrics.performance_indicators.response_time > 5000) score -= 10;
  if (metrics.performance_indicators.availability < 95) score -= 15;

  // Error rate penalties
  Object.values(metrics.error_rates).forEach(rate => {
    if (rate > 5) score -= 10;
    if (rate > 10) score -= 20;
  });

  return Math.max(0, score);
}

function analyzeSystemPerformance(campaignId, systemMetrics, worldState) {
  const analysis = {
    performance_score: 0,
    bottlenecks: [],
    recommendations: [],
    trends: {},
    capacity_utilization: {},
    response_patterns: {}
  };

  if (!systemMetrics) {
    analysis.performance_score = 0;
    analysis.bottlenecks.push('no_metrics_available');
    return analysis;
  }

  // Calculate performance score
  let score = 100;

  // Response time scoring
  if (systemMetrics.average_response_time > 1000) score -= 10;
  if (systemMetrics.average_response_time > 3000) score -= 20;
  if (systemMetrics.average_response_time > 5000) score -= 30;

  // Throughput scoring
  if (systemMetrics.throughput < 10) score -= 5;
  if (systemMetrics.throughput < 5) score -= 15;

  // Error rate scoring
  if (systemMetrics.error_rate > 1) score -= 10;
  if (systemMetrics.error_rate > 5) score -= 25;

  // Resource usage scoring
  if (systemMetrics.cpu_usage > 0.7) score -= 10;
  if (systemMetrics.cpu_usage > 0.9) score -= 20;

  if (systemMetrics.memory_usage > 0.8) score -= 10;
  if (systemMetrics.memory_usage > 0.95) score -= 25;

  analysis.performance_score = Math.max(0, score);

  // Identify bottlenecks
  if (systemMetrics.average_response_time > 3000) {
    analysis.bottlenecks.push({
      type: 'response_time',
      severity: systemMetrics.average_response_time > 5000 ? 'high' : 'medium',
      value: systemMetrics.average_response_time,
      threshold: 3000
    });
  }

  if (systemMetrics.memory_usage > 0.8) {
    analysis.bottlenecks.push({
      type: 'memory_usage',
      severity: systemMetrics.memory_usage > 0.95 ? 'high' : 'medium',
      value: systemMetrics.memory_usage,
      threshold: 0.8
    });
  }

  if (systemMetrics.cpu_usage > 0.7) {
    analysis.bottlenecks.push({
      type: 'cpu_usage',
      severity: systemMetrics.cpu_usage > 0.9 ? 'high' : 'medium',
      value: systemMetrics.cpu_usage,
      threshold: 0.7
    });
  }

  if (systemMetrics.error_rate > 5) {
    analysis.bottlenecks.push({
      type: 'error_rate',
      severity: systemMetrics.error_rate > 10 ? 'high' : 'medium',
      value: systemMetrics.error_rate,
      threshold: 5
    });
  }

  // Generate recommendations
  if (systemMetrics.memory_usage > 0.8) {
    analysis.recommendations.push({
      type: 'optimization',
      priority: 'high',
      description: 'Optimize memory usage or increase memory allocation',
      action: 'memory_optimization'
    });
  }

  if (systemMetrics.average_response_time > 3000) {
    analysis.recommendations.push({
      type: 'performance',
      priority: 'medium',
      description: 'Investigate and optimize slow response times',
      action: 'response_optimization'
    });
  }

  if (systemMetrics.error_rate > 5) {
    analysis.recommendations.push({
      type: 'reliability',
      priority: 'high',
      description: 'Address high error rate to improve reliability',
      action: 'error_reduction'
    });
  }

  // Capacity utilization analysis
  analysis.capacity_utilization = {
    cpu: systemMetrics.cpu_usage || 0,
    memory: systemMetrics.memory_usage || 0,
    disk: systemMetrics.disk_usage || 0,
    network: systemMetrics.network_usage || 0
  };

  return analysis;
}

function detectAnomalies(campaignId, healthMetrics, performanceAnalysis, thresholds) {
  const anomalies = {
    detected: [],
    severity_distribution: { low: 0, medium: 0, high: 0, critical: 0 },
    anomaly_patterns: [],
    alert_required: false,
    last_anomaly_time: null
  };

  // Health anomalies
  if (healthMetrics.overall_health === 'critical') {
    anomalies.detected.push({
      type: 'health_critical',
      severity: 'critical',
      description: 'Overall system health is critical',
      timestamp: new Date().toISOString(),
      affected_systems: ['all'],
      recommended_action: 'immediate_investigation'
    });
    anomalies.severity_distribution.critical++;
    anomalies.alert_required = true;
  }

  // Performance anomalies
  if (performanceAnalysis.performance_score < 70) {
    anomalies.detected.push({
      type: 'performance_degradation',
      severity: performanceAnalysis.performance_score < 50 ? 'high' : 'medium',
      description: `Performance score is ${performanceAnalysis.performance_score}%`,
      timestamp: new Date().toISOString(),
      affected_systems: ['system'],
      bottlenecks: performanceAnalysis.bottlenecks,
      recommended_action: 'performance_optimization'
    });

    const severity = performanceAnalysis.performance_score < 50 ? 'high' : 'medium';
    anomalies.severity_distribution[severity]++;

    if (severity === 'high') {
      anomalies.alert_required = true;
    }
  }

  // Data integrity anomalies
  Object.entries(healthMetrics.data_integrity).forEach(([component, integrity]) {
    if (integrity.issue_count > 0) {
      const severity = integrity.issue_count > 5 ? 'high' : 'medium';

      anomalies.detected.push({
        type: 'data_integrity_issue',
        severity,
        component,
        description: `${integrity.issue_count} integrity issues found in ${component}`,
        timestamp: new Date().toISOString(),
        affected_systems: [component],
        issues: integrity.issues,
        recommended_action: 'data_repair'
      });

      anomalies.severity_distribution[severity]++;
    }
  });

  // Error rate anomalies
  Object.entries(healthMetrics.error_rates).forEach(([error_type, rate]) => {
    if (rate > thresholds.error_rate * 100) {
      anomalies.detected.push({
        type: 'elevated_error_rate',
        severity: rate > thresholds.error_rate * 200 ? 'high' : 'medium',
        error_type,
        description: `${error_type} error rate is ${rate.toFixed(2)}%`,
        timestamp: new Date().toISOString(),
        threshold: thresholds.error_rate * 100,
        recommended_action: 'error_investigation'
      });

      const severity = rate > thresholds.error_rate * 200 ? 'high' : 'medium';
      anomalies.severity_distribution[severity]++;
    }
  });

  // Update last anomaly time if anomalies were detected
  if (anomalies.detected.length > 0) {
    const latestAnomaly = anomalies.detected.reduce((latest, anomaly) => 
      new Date(anomaly.timestamp) > new Date(latest.timestamp) ? anomaly : latest
    );
    anomalies.last_anomaly_time = latestAnomaly.timestamp;
  }

  return anomalies;
}

function generateLogEntries(campaignId, healthMetrics, performanceAnalysis, anomalyDetection, loggingParameters) {
  const logEntries = [];
  const timestamp = new Date().toISOString();

  // Health log entry
  logEntries.push({
    id: `log_${campaignId}_health_${Date.now()}`,
    timestamp,
    level: healthMetrics.overall_health === 'critical' ? 'error' : 
           healthMetrics.overall_health === 'warning' ? 'warn' : 'info',
    category: 'health',
    campaign_id: campaignId,
    message: `Health status: ${healthMetrics.overall_health}`,
    details: {
      overall_health: healthMetrics.overall_health,
      system_health: healthMetrics.system_health,
      data_integrity: healthMetrics.data_integrity,
      error_rates: healthMetrics.error_rates
    },
    correlation_id: `monitor_${campaignId}_${Date.now()}`
  });

  // Performance log entry
  logEntries.push({
    id: `log_${campaignId}_performance_${Date.now()}`,
    timestamp,
    level: performanceAnalysis.performance_score < 70 ? 'warn' : 'info',
    category: 'performance',
    campaign_id: campaignId,
    message: `Performance score: ${performanceAnalysis.performance_score}%`,
    details: {
      performance_score: performanceAnalysis.performance_score,
      bottlenecks: performanceAnalysis.bottlenecks,
      capacity_utilization: performanceAnalysis.capacity_utilization,
      recommendations: performanceAnalysis.recommendations
    },
    correlation_id: `monitor_${campaignId}_${Date.now()}`
  });

  // Anomaly log entries
  anomalyDetection.detected.forEach(anomaly => {
    logEntries.push({
      id: `log_${campaignId}_anomaly_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
      timestamp: anomaly.timestamp,
      level: anomaly.severity === 'critical' ? 'fatal' : 
             anomaly.severity === 'high' ? 'error' : 
             anomaly.severity === 'medium' ? 'warn' : 'info',
      category: 'anomaly',
      campaign_id: campaignId,
      message: anomaly.description,
      details: anomaly,
      correlation_id: `monitor_${campaignId}_${Date.now()}`,
      alert_required: anomalyDetection.alert_required
    });
  });

  // System metrics log entry
  logEntries.push({
    id: `log_${campaignId}_metrics_${Date.now()}`,
    timestamp,
    level: 'info',
    category: 'metrics',
    campaign_id: campaignId,
    message: 'System metrics collected',
    details: {
      performance_indicators: healthMetrics.performance_indicators,
      resource_usage: performanceAnalysis.capacity_utilization
    },
    correlation_id: `monitor_${campaignId}_${Date.now()}`
  });

  return logEntries;
}

function calculateMonitoringPriority(healthMetrics, anomalyDetection) {
  let priority = 5;

  // Health-based priority
  if (healthMetrics.overall_health === 'critical') priority += 5;
  if (healthMetrics.overall_health === 'warning') priority += 3;

  // Anomaly-based priority
  priority += anomalyDetection.severity_distribution.critical * 5;
  priority += anomalyDetection.severity_distribution.high * 3;
  priority += anomalyDetection.severity_distribution.medium * 1;

  // Data integrity issues
  const totalIntegrityIssues = Object.values(healthMetrics.data_integrity)
    .reduce((sum, integrity) => sum + integrity.issue_count, 0);
  priority += totalIntegrityIssues * 2;

  return Math.min(priority, 10);
}

return [{
  json: {
    ...monitoringConfig,
    campaigns: processedCampaigns,
    total_campaigns: processedCampaigns.length,
    monitoring_timestamp: new Date().toISOString()
  }
}];

// Generate alerts and notifications for campaign
const monitoringConfig = $input.first().json;
const campaign = $input.first().json.campaigns[$input.first().json.currentCampaignIndex || 0];

const { campaignId, healthMetrics, performanceAnalysis, anomalyDetection, logEntries } = campaign;

const alerts = [];
const notifications = [];

// Generate alerts based on health and anomalies
if (healthMetrics.overall_health === 'critical') {
  alerts.push({
    id: `alert_critical_${campaignId}_${Date.now()}`,
    type: 'critical_health',
    severity: 'critical',
    title: `CRITICAL: Campaign ${campaignId} Health Status`,
    message: `Campaign health status is critical. Immediate attention required.`,
    campaign_id: campaignId,
    timestamp: new Date().toISOString(),
    details: {
      overall_health: healthMetrics.overall_health,
      system_health: healthMetrics.system_health,
      data_integrity_issues: Object.values(healthMetrics.data_integrity).reduce((sum, integrity) => sum + integrity.issue_count, 0),
      error_rates: healthMetrics.error_rates
    },
    recommended_actions: [
      'Investigate system health immediately',
      'Check data integrity issues',
      'Review error rates and system metrics',
      'Consider emergency recovery procedures'
    ],
    escalation_required: true,
    auto_escalate: true
  });
}

if (healthMetrics.overall_health === 'warning') {
  alerts.push({
    id: `alert_warning_${campaignId}_${Date.now()}`,
    type: 'warning_health',
    severity: 'warning',
    title: `WARNING: Campaign ${campaignId} Health Status`,
    message: `Campaign health status requires attention.`,
    campaign_id: campaignId,
    timestamp: new Date().toISOString(),
    details: {
      overall_health: healthMetrics.overall_health,
      performance_score: performanceAnalysis.performance_score,
      bottlenecks: performanceAnalysis.bottlenecks
    },
    recommended_actions: performanceAnalysis.recommendations,
    escalation_required: false,
    auto_escalate: false
  });
}

// Generate alerts for anomalies
anomalyDetection.detected.forEach(anomaly => {
  if (anomaly.severity === 'critical' || anomaly.severity === 'high') {
    alerts.push({
      id: `alert_anomaly_${campaignId}_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
      type: 'anomaly_detected',
      severity: anomaly.severity,
      title: `${anomaly.severity.toUpperCase()}: ${anomaly.type.replace('_', ' ').toUpperCase()}`,
      message: anomaly.description,
      campaign_id: campaignId,
      timestamp: anomaly.timestamp,
      details: anomaly,
      recommended_actions: [anomaly.recommended_action],
      escalation_required: anomaly.severity === 'critical',
      auto_escalate: anomaly.severity === 'critical'
    });
  }
});

// Generate performance alerts
if (performanceAnalysis.performance_score < 60) {
  alerts.push({
    id: `alert_performance_${campaignId}_${Date.now()}`,
    type: 'performance_issue',
    severity: performanceAnalysis.performance_score < 40 ? 'high' : 'medium',
    title: `Performance Issue in Campaign ${campaignId}`,
    message: `Performance score is ${performanceAnalysis.performance_score}%`,
    campaign_id: campaignId,
    timestamp: new Date().toISOString(),
    details: {
      performance_score: performanceAnalysis.performance_score,
      bottlenecks: performanceAnalysis.bottlenecks,
      capacity_utilization: performanceAnalysis.capacity_utilization
    },
    recommended_actions: performanceAnalysis.recommendations,
    escalation_required: false,
    auto_escalate: false
  });
}

// Generate data integrity alerts
const totalIntegrityIssues = Object.values(healthMetrics.data_integrity)
  .reduce((sum, integrity) => sum + integrity.issue_count, 0);

if (totalIntegrityIssues > 0) {
  alerts.push({
    id: `alert_integrity_${campaignId}_${Date.now()}`,
    type: 'data_integrity',
    severity: totalIntegrityIssues > 10 ? 'high' : 'medium',
    title: `Data Integrity Issues in Campaign ${campaignId}`,
    message: `${totalIntegrityIssues} data integrity issues detected`,
    campaign_id: campaignId,
    timestamp: new Date().toISOString(),
    details: {
      total_issues: totalIntegrityIssues,
      integrity_details: healthMetrics.data_integrity
    },
    recommended_actions: [
      'Run data integrity repair procedures',
      'Check for orphaned references',
      'Validate data consistency',
      'Review data entry processes'
    ],
    escalation_required: totalIntegrityIssues > 20,
    auto_escalate: false
  });
}

// Generate notifications for general monitoring
notifications.push({
  id: `notification_monitoring_${campaignId}_${Date.now()}`,
  type: 'monitoring_summary',
  severity: 'info',
  title: `Monitoring Summary for Campaign ${campaignId}`,
  message: `Regular monitoring cycle completed`,
  campaign_id: campaignId,
  timestamp: new Date().toISOString(),
  details: {
    health_status: healthMetrics.overall_health,
    performance_score: performanceAnalysis.performance_score,
    anomalies_detected: anomalyDetection.detected.length,
    alerts_generated: alerts.length,
    log_entries_created: logEntries.length
  },
  recipients: ['admin', 'operators'],
  channels: ['dashboard', 'email']
});

// Generate notification if no critical issues
if (alerts.length === 0 && healthMetrics.overall_health === 'healthy') {
  notifications.push({
    id: `notification_healthy_${campaignId}_${Date.now()}`,
    type: 'health_status',
    severity: 'success',
    title: `All Systems Healthy for Campaign ${campaignId}`,
    message: `All systems operating normally`,
    campaign_id: campaignId,
    timestamp: new Date().toISOString(),
    details: {
      health_status: healthMetrics.overall_health,
      performance_score: performanceAnalysis.performance_score,
      uptime: performanceAnalysis.capacity_utilization
    },
    recipients: ['admin'],
    channels: ['dashboard']
  });
}

return [{
  json: {
    campaignId,
    alerts,
    notifications,
    log_entries: logEntries,
    health_summary: {
      overall_health: healthMetrics.overall_health,
      performance_score: performanceAnalysis.performance_score,
      anomaly_count: anomalyDetection.detected.length,
      alert_count: alerts.length,
      log_count: logEntries.length
    },
    timestamp: new Date().toISOString()
  }
}];

// Generate monitoring summary report
const monitoringData = $input.first().json;

const summary = {
  monitoring_id: `monitor_summary_${Date.now()}_${Math.random().toString(36).substr(2, 8)}`,
  campaign_id: monitoringData.campaignId,
  processing_time: new Date().toISOString(),
  monitoring_cycle: {
    campaigns_monitored: 1,
    alerts_generated: monitoringData.alerts.length,
    notifications_sent: monitoringData.notifications.length,
    log_entries_created: monitoringData.log_entries.length,
    processing_duration: Date.now() - new Date(monitoringData.timestamp).getTime()
  },
  health_summary: monitoringData.health_summary,
  alert_analysis: {
    total_alerts: monitoringData.alerts.length,
    critical_alerts: monitoringData.alerts.filter(a => a.severity === 'critical').length,
    high_alerts: monitoringData.alerts.filter(a => a.severity === 'high').length,
    medium_alerts: monitoringData.alerts.filter(a => a.severity === 'medium').length,
    low_alerts: monitoringData.alerts.filter(a => a.severity === 'low').length,
    alerts_by_type: categorizeAlerts(monitoringData.alerts),
    escalation_required: monitoringData.alerts.some(a => a.escalation_required),
    auto_escalated: monitoringData.alerts.filter(a => a.auto_escalate).length
  },
  system_health_trends: {
    current_status: monitoringData.health_summary.overall_health,
    performance_trend: 'stable', // Would calculate from historical data
    error_rate_trend: 'stable', // Would calculate from historical data
    resource_usage_trend: 'stable' // Would calculate from historical data
  },
  recommendations: generateMonitoringRecommendations(monitoringData),
  next_steps: generateNextSteps(monitoringData),
  compliance_status: checkComplianceStatus(monitoringData)
};

function categorizeAlerts(alerts) {
  const categories = {};

  alerts.forEach(alert => {
    if (!categories[alert.type]) {
      categories[alert.type] = {
        total: 0,
        critical: 0,
        high: 0,
        medium: 0,
        low: 0
      };
    }

    categories[alert.type].total++;
    categories[alert.type][alert.severity]++;
  });

  return categories;
}

function generateMonitoringRecommendations(monitoringData) {
  const recommendations = [];

  // Health-based recommendations
  if (monitoringData.health_summary.overall_health !== 'healthy') {
    recommendations.push({
      type: 'health_improvement',
      priority: 'high',
      description: 'Investigate and resolve health issues',
      action_items: ['Review system logs', 'Check resource utilization', 'Verify data integrity']
    });
  }

  // Performance-based recommendations
  if (monitoringData.health_summary.performance_score < 80) {
    recommendations.push({
      type: 'performance_optimization',
      priority: 'medium',
      description: 'Optimize system performance',
      action_items: ['Identify bottlenecks', 'Optimize resource usage', 'Review system configuration']
    });
  }

  // Alert-based recommendations
  if (monitoringData.alerts.length > 0) {
    recommendations.push({
      type: 'alert_management',
      priority: 'high',
      description: 'Address active alerts',
      action_items: ['Review alert details', 'Implement corrective actions', 'Monitor for resolution']
    });
  }

  // Monitoring improvement recommendations
  recommendations.push({
    type: 'monitoring_enhancement',
    priority: 'low',
    description: 'Enhance monitoring coverage',
    action_items: ['Add custom metrics', 'Improve alert thresholds', 'Expand monitoring scope']
  });

  return recommendations;
}

function generateNextSteps(monitoringData) {
  const steps = [];

  // Immediate next steps based on alerts
  if (monitoringData.alerts.some(a => a.severity === 'critical')) {
    steps.push({
      action: 'immediate_response',
      description: 'Respond to critical alerts immediately',
      priority: 'urgent',
      timeline: 'immediate',
      responsible: 'operations_team'
    });
  }

  // Standard monitoring tasks
  steps.push({
    action: 'log_review',
    description: 'Review monitoring logs and metrics',
    priority: 'medium',
    timeline: 'next_4_hours',
    responsible: 'monitoring_team'
  });

  steps.push({
    action: 'performance_analysis',
    description: 'Analyze performance trends and patterns',
    priority: 'medium',
    timeline: 'next_24_hours',
    responsible: 'performance_team'
  });

  steps.push({
    action: 'report_generation',
    description: 'Generate comprehensive monitoring report',
    priority: 'low',
    timeline: 'next_week',
    responsible: 'monitoring_team'
  });

  return steps;
}

function checkComplianceStatus(monitoringData) {
  const compliance = {
    status: 'compliant',
    issues: [],
    last_check: new Date().toISOString()
  };

  // Check alert compliance
  if (monitoringData.alerts.some(a => a.severity === 'critical' && !a.escalation_required)) {
    compliance.issues.push('Critical alerts without escalation');
    compliance.status = 'non_compliant';
  }

  // Check log compliance
  if (monitoringData.log_entries.length === 0) {
    compliance.issues.push('No log entries generated');
    compliance.status = 'non_compliant';
  }

  // Check notification compliance
  if (monitoringData.alerts.length > 0 && monitoringData.notifications.length === 0) {
    compliance.issues.push('Alerts generated without notifications');
    compliance.status = 'non_compliant';
  }

  return compliance;
}

return [{ json: summary }];
